// Paths are on the Linux SSH host. Match project to request.json.
// Keep runId to reconnect; change it for a new attempt or after changing mode.
const repo = '/srv/rnaseq/RNASeq_pipeline-3.0';
const request = '/srv/rnaseq/requests/my_study.json';
const project = '/srv/rnaseq/projects/my_study';
const runId = 'my-study-check-001';
const expectedSource = 'c0927cf7f31e0fc603c39eec9b432f9efcdcbbc53971d422dfe1ba2b2de6750c';
const action = 'start'; // 'status' reconnects without launching anything
if (!['start', 'status'].includes(action)) throw new Error('Invalid action');
if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(runId)) throw new Error('Invalid runId');
for (const p of [repo, request, project]) {
  if (!p.startsWith('/') || /[\r\n\0]/.test(p)) throw new Error('Use absolute host paths');
}
const q = s => "'" + s.replace(/'/g, "'\"'\"'") + "'";
const runner = `python3 ${q(repo + '/integrations/n8n/runner.py')}`;
const poll = `${runner} status --project ${q(project)} --run-id ${q(runId)}`;
const start = `${runner} start --request ${q(request)} --project ${q(project)} --run-id ${q(runId)}`;
const sshHost = 'analysis-host'; // Host alias from this n8n host's ~/.ssh/config
if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(sshHost)) throw new Error('Invalid SSH alias');
const viaSsh = command => `/usr/bin/ssh -o BatchMode=yes -o ConnectTimeout=15 -- ${q(sshHost)} ${q('bash -lc ' + q(command))}`;
return [{json: {project, runId, action, expectedSource, inspectCommand: viaSsh(`${runner} inspect --repo ${q(repo)}`), startCommand: viaSsh(action === 'status' ? poll : start),
  pollCommand: viaSsh(poll), monitoringStarted: Date.now(), maxHours: 168}}];

const response = $input.first().json;
if (response.exitCode !== 0) throw new Error('Remote command failed: ' + (response.stderr || response.stdout));
let state;
try { state = JSON.parse(response.stdout); } catch { throw new Error('Invalid runner JSON: ' + response.stdout); }
const cfg = $('Settings').first().json;
if (state.project !== cfg.project || state.run_id !== cfg.runId) throw new Error('Project/run identity mismatch; inspect the remote run');
if (!['running','succeeded','failed','interrupted'].includes(state.status)) throw new Error('Unknown run status');
if (state.status === 'running' && Date.now() - cfg.monitoringStarted > cfg.maxHours * 3600000)
  throw new Error('Monitoring timeout; remote work is NOT cancelled. Reconnect with action=status and the same runId.');
return [{json: state}];

return $input.all().map(item => {
  const s = item.json;
  return {json: {...s, route: s.reports?.recommendation?.route || (s.mode === 'raw_qc' ? 'independent_raw_qc' : 'see controller log'),
    next_step: s.mode === 'dry_run' ? 'Review recommendations, stages, storage cautions and configuration. Set mode=run and choose a new runId.' : 'Review assay-specific counts/QC, count treatment, contrast directions and optional-analysis manifests. See raw_qc_report for independent raw QC.'}};
});

const r=$input.first().json;
if(r.exitCode!==0) throw new Error('Cannot inspect deployed pipeline: '+(r.stderr || r.stdout));
const source=JSON.parse(r.stdout), cfg=$('Settings').first().json;
if(cfg.action==='start' && source.source_sha256!==cfg.expectedSource)
  throw new Error('Wrong or modified pipeline checkout. Deploy the reviewed 3.0 bundle; do not bypass this check blindly.');
return [{json:{...cfg,deployedPipeline:source}}];
